import { Block, Text } from "@prototyp/skeletor";
import { useAtomValue, useSetAtom } from "jotai";
import { MatrixService } from "modules/matrix-client/services";
import { type FC, useEffect, useState } from "react";
import { Modal } from "react-native";
import Toast from "react-native-toast-message";
import { Button, Loading } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { MatrixAtoms } from "../jotai";

type VerificationState = {
  isVerifying: boolean;
  stage: "request" | "accepted" | "emojis" | "sasStarted";
  emojis: Array<{ symbol: string; description: string }> | null;
  senderName: string | null;
  senderId: string | null;
  flowId: string | null;
};

export const VerificationProvider: FC = () => {
  const client = useAtomValue(MatrixAtoms.matrixClient);
  const syncService = useAtomValue(MatrixAtoms.syncService);
  const [matchLoading, setMatchLoading] = useState(false);
  const [startLoading, setStartLoading] = useState(false);
  const [verificationState, setVerificationState] = useState<VerificationState>(
    {
      isVerifying: false,
      stage: "request",
      emojis: null,
      senderName: null,
      senderId: null,
      flowId: null,
    },
  );
  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);

  useEffect(() => {
    if (!client || !syncService) return;
    // Set up verification listeners when component mounts
    const setupVerificationListeners = async () => {
      try {
        const unsubscribe = await MatrixService.setupVerification(
          // On verification request received
          (details) => {
            setVerificationState({
              isVerifying: true,
              stage: "request",
              emojis: null,
              senderName:
                details.senderProfile.displayName ||
                details.senderProfile.userId,
              senderId: details.senderProfile.userId,
              flowId: details.flowId,
            });
          },
          // On emojis received
          (emojis) => {
            setMatchLoading(false);
            setStartLoading(false);
            setVerificationStatus("emojis");
            setVerificationState((prev) => ({
              ...prev,
              isVerifying: true,
              stage: "emojis",
              emojis,
              senderName: prev.senderName ?? "the other device",
            }));
          },
          // On state change
          (state) => {
            console.log("Verification state changed:", state);

            if (state === "success") {
              setVerificationStatus("success");
              setMatchLoading(false);
              setStartLoading(false);
              Toast.show({
                type: "success",
                text1: "Device verified successfully! 🎉",
              });
              setVerificationState({
                isVerifying: false,
                stage: "request",
                emojis: null,
                senderName: null,
                senderId: null,
                flowId: null,
              });
            } else if (state === "failed") {
              setVerificationStatus("failed");
              setMatchLoading(false);
              setStartLoading(false);
              Toast.show({
                type: "error",
                text1: "Verification failed",
              });
              setVerificationState({
                isVerifying: false,
                stage: "request",
                emojis: null,
                senderName: null,
                senderId: null,
                flowId: null,
              });
            } else if (state === "cancelled") {
              setVerificationStatus("cancelled");
              setMatchLoading(false);
              setStartLoading(false);
              Toast.show({
                type: "error",
                text1: "Verification cancelled",
              });
              setVerificationState({
                isVerifying: false,
                stage: "request",
                emojis: null,
                senderName: null,
                senderId: null,
                flowId: null,
              });
            } else if (state === "emojis") {
              setVerificationStatus("emojis");
            } else if (state === "accepted") {
              setVerificationStatus("accepted");
              setVerificationState((prev) => ({
                ...prev,
                stage: "accepted",
              }));
            } else if (state === "sasStarted") {
              setVerificationStatus("sasStarted");
              setVerificationState((prev) => ({
                ...prev,
                stage: "sasStarted",
              }));
            }
          },
        );
        return unsubscribe;
      } catch (error) {
        console.error("Failed to set up verification:", error);
      } finally {
        setVerificationStatus("idle");
      }
    };

    setupVerificationListeners();
  }, [client, syncService]);

  const handleEmojiMatch = async (match: boolean) => {
    try {
      if (match) {
        await MatrixService.approveVerification();
      } else {
        await MatrixService.declineVerification();
        Toast.show({
          type: "error",
          text1: "Verification Declined",
          text2:
            "The emojis didn't match. This could indicate a security issue.",
        });
      }
    } catch (error) {
      console.error("Failed to complete verification:", error);
      Toast.show({
        type: "error",
        text1: "Failed to complete verification",
      });
    }
  };

  const handleAcceptVerification = async () => {
    if (!verificationState.senderId || !verificationState.flowId) return;
    try {
      await MatrixService.acknowledgeVerification(
        verificationState.senderId,
        verificationState.flowId,
      );
      await MatrixService.acceptVerificationRequest();
      setVerificationState((prev) => ({
        ...prev,
        stage: "accepted",
      }));
    } catch (error) {
      console.error("Failed to accept verification:", error);
      Toast.show({
        type: "error",
        text1: "Failed to accept verification",
      });
    }
  };

  const handleStartEmojiVerification = async () => {
    try {
      setStartLoading(true);
      await MatrixService.startVerification();
    } catch (error) {
      console.error("Failed to start emoji verification:", error);
      setStartLoading(false);
      Toast.show({
        type: "error",
        text1: "Failed to start emoji verification",
      });
    }
  };

  const handleCancelVerification = async () => {
    if (!verificationState.senderId || !verificationState.flowId) return;
    try {
      await MatrixService.acknowledgeVerification(
        verificationState.senderId,
        verificationState.flowId,
      );
      await MatrixService.cancelVerification();
      setVerificationStatus("cancelled");
      setVerificationState({
        isVerifying: false,
        stage: "request",
        emojis: null,
        senderName: null,
        senderId: null,
        flowId: null,
      });
    } catch (error) {
      console.error("Failed to cancel verification:", error);
      Toast.show({
        type: "error",
        text1: "Failed to cancel verification",
      });
    }
  };

  return (
    <>
      <Modal
        visible={verificationState.isVerifying}
        transparent
        animationType="fade"
      >
        <Block
          flex={1}
          justify="center"
          align="center"
          background={Colors.black70}
        >
          <Block
            background={Colors.blackMinus2}
            paddings={24}
            border={{ borderRadius: 36 }}
            gap={24}
            width="100%"
          >
            <Text
              textAlign="center"
              size={TextSize.large}
              font="InstrumentSans-Bold"
            >
              Verify Device
            </Text>
            {startLoading && (
              <Block flex={1} align="center" justify="center" margins={40}>
                <Loading
                  text="Waiting for verification from other device..."
                  isFullScreen={false}
                />
              </Block>
            )}
            {verificationState.stage === "request" && (
              <>
                <Text textAlign="center" size={TextSize.large}>
                  {verificationState.senderName} wants to verify this device.
                </Text>
                <Text
                  textAlign="center"
                  size={TextSize.small}
                  color={Colors.white50}
                >
                  Accept the request to continue.
                </Text>
                <Block
                  flexDirection="row"
                  justify="space-between"
                  gap={12}
                  width="100%"
                >
                  <Block flex={1}>
                    <Button.Warning onPress={handleCancelVerification}>
                      Ignore
                    </Button.Warning>
                  </Block>
                  <Block flex={1}>
                    <Button.Primary onPress={handleAcceptVerification}>
                      Accept
                    </Button.Primary>
                  </Block>
                </Block>
              </>
            )}

            {verificationState.stage === "accepted" && (
              <>
                <Text
                  textAlign="center"
                  size={TextSize.large}
                  font="InstrumentSans-Bold"
                >
                  Request accepted. Start emoji verification.
                </Text>
                <Block flexDirection="row" justify="space-between" gap={12}>
                  <Block flex={1}>
                    <Button.Warning
                      onPress={handleCancelVerification}
                      width="100%"
                    >
                      Cancel
                    </Button.Warning>
                  </Block>
                  <Block flex={1}>
                    <Button.Primary
                      onPress={handleStartEmojiVerification}
                      width="100%"
                    >
                      {startLoading
                        ? "Starting verification..."
                        : "Start verification"}
                    </Button.Primary>
                  </Block>
                </Block>
              </>
            )}

            {verificationState.stage === "emojis" && (
              <>
                <Text textAlign="center" size={TextSize.large}>
                  Compare these emojis with {verificationState.senderName}
                </Text>

                <Block
                  flexDirection="row"
                  flex={{ flexWrap: "wrap" }}
                  justify="center"
                  gap={16}
                  width="100%"
                >
                  {verificationState.emojis?.map((emoji, index) => (
                    <Block key={index} align="center" minWidth={80}>
                      <Text textAlign="center" size={TextSize.large}>
                        {emoji.symbol}
                      </Text>
                      <Text
                        textAlign="center"
                        size={TextSize.small}
                        color={Colors.white50}
                      >
                        {emoji.description}
                      </Text>
                    </Block>
                  ))}
                </Block>

                <Text
                  textAlign="center"
                  size={TextSize.small}
                  color={Colors.white50}
                >
                  Do these emojis match on both devices?
                </Text>

                <Block
                  flexDirection="row"
                  justify="space-between"
                  gap={12}
                  width="100%"
                >
                  {matchLoading ? (
                    <Loading
                      text="Waiting verification from other device..."
                      isFullScreen={false}
                    />
                  ) : (
                    <>
                      <Block flex={1}>
                        <Button.Warning onPress={() => handleEmojiMatch(false)}>
                          They Don't Match
                        </Button.Warning>
                      </Block>
                      <Block flex={1}>
                        <Button.Primary
                          onPress={() => {
                            handleEmojiMatch(true);
                            setMatchLoading(true);
                          }}
                        >
                          They Match
                        </Button.Primary>
                      </Block>
                    </>
                  )}
                </Block>
              </>
            )}
          </Block>
        </Block>
      </Modal>
    </>
  );
};

