type Asset = import("react-native-image-picker").Asset;
type RoomInterface = import("@unomed/react-native-matrix-sdk").RoomInterface;
type RoomMember = import("@unomed/react-native-matrix-sdk").RoomMember;

type Routes = {
  splash: undefined;
  login: undefined;
  home: undefined;
  welcome: undefined;
  onboarding: undefined;
  forgotPassword: undefined;
  startChat: undefined;
  createRoom: undefined;
  invitePeople: {
    roomId: string;
    members: RoomMember[];
    isCreateRoom?: boolean;
  };
  joinRoom: undefined;
  room: {
    roomId: string;
  };
  sendImages: {
    roomId: string;
    images: Asset[];
  };
  elementCall: {
    roomId: string;
    roomName?: string;
  };
  editRoom: {
    room: RoomInterface;
  };
  setUpRecoveryKey: undefined;
  settings: undefined;
  verifyUser: {
    userId: string;
    /** If provided, this is an incoming verification request that needs to be acknowledged */
    flowId?: string;
  };
  profile: {
    userId: string;
  };
  userProfile: undefined;
  notifications: undefined;
  notificationsIntro: undefined;
  screenLock: undefined;
  screenLockSettings: undefined;
  setupScreenLock: undefined;
  verifyPin: { isSettingsScreen?: boolean };
  encryption: undefined;
  about: undefined;
  reportProblem: undefined;
  roomDetails: { room: RoomInterface };
  roomNotifications: undefined;
  roomMembers: {
    members: RoomMember[];
    roomId: string;
  };
  roomMedia: {
    room: RoomInterface;
  };
  confirmIdentity: undefined;
  cantConfirm: undefined;
  enterRecoveryKey: undefined;
  verifyWithDevice: undefined;
  notificationsType: {
    type: "group" | "direct";
    notificationsType: "all" | "mentions" | "none";
  };
};

import {
  createStackNavigator,
  TransitionPresets,
} from "@react-navigation/stack";
import type { FC, PropsWithChildren } from "react";
import { Platform } from "react-native";
import {
  About,
  CantConfirm,
  ConfirmIdentity,
  CreateRoom,
  EditRoom,
  ElementCall,
  Encryption,
  EnterRecoveryKey,
  Home,
  InvitePeople,
  Login,
  Notifications,
  NotificationsIntro,
  NotificationsType,
  Onboarding,
  Profile,
  Room,
  RoomDetails,
  RoomMedia,
  RoomMembers,
  RoomNotifications,
  ScreenLockSettings,
  SendImages,
  Settings,
  SetUpRecoveryKey,
  SetupScreenLock,
  Splash,
  StartChat,
  UserProfile,
  VerifyPin,
  VerifyUser,
  VerifyWithDevice,
  Welcome,
} from "screens";

const Stack = createStackNavigator<Routes>();

export const RootNavigator: FC<PropsWithChildren> = ({ children }) => {
  return (
    <Stack.Navigator screenOptions={{ headerShown: false }}>
      <Stack.Screen name="splash" component={Splash} />
      <Stack.Screen name="about" component={About} />
      <Stack.Screen name="login" component={Login} />
      <Stack.Screen name="home" component={Home} />
      <Stack.Screen name="welcome" component={Welcome} />
      <Stack.Screen name="room" component={Room} />
      <Stack.Screen name="settings" component={Settings} />
      <Stack.Screen name="userProfile" component={UserProfile} />
      <Stack.Screen name="profile" component={Profile} />
      <Stack.Screen name="notifications" component={Notifications} />
      <Stack.Screen name="screenLockSettings" component={ScreenLockSettings} />
      <Stack.Screen name="setupScreenLock" component={SetupScreenLock} />
      <Stack.Screen name="verifyPin" component={VerifyPin} />
      <Stack.Screen name="roomDetails" component={RoomDetails} />
      <Stack.Screen name="encryption" component={Encryption} />
      <Stack.Screen name="editRoom" component={EditRoom} />
      <Stack.Screen name="roomNotifications" component={RoomNotifications} />
      <Stack.Screen name="roomMedia" component={RoomMedia} />
      <Stack.Screen name="roomMembers" component={RoomMembers} />
      <Stack.Screen name="confirmIdentity" component={ConfirmIdentity} />
      <Stack.Screen
        name="enterRecoveryKey"
        component={EnterRecoveryKey}
        options={{
          presentation: "modal",
          gestureEnabled: Platform.OS === "ios",
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      <Stack.Screen name="verifyWithDevice" component={VerifyWithDevice} />
      <Stack.Screen name="notificationsType" component={NotificationsType} />
      <Stack.Screen name="onboarding" component={Onboarding} />
      <Stack.Screen name="notificationsIntro" component={NotificationsIntro} />
      <Stack.Screen
        name="verifyUser"
        component={VerifyUser}
        options={{
          presentation: "modal",
          gestureEnabled: false,
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      <Stack.Screen
        name="cantConfirm"
        component={CantConfirm}
        options={{
          presentation: "modal",
          gestureEnabled: Platform.OS === "ios",
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      <Stack.Screen
        name="startChat"
        component={StartChat}
        options={{
          presentation: "modal",
          gestureEnabled: Platform.OS === "ios",
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      <Stack.Screen
        name="invitePeople"
        component={InvitePeople}
        options={{
          presentation: "modal",
          gestureEnabled: Platform.OS === "ios",
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      <Stack.Screen
        name="createRoom"
        component={CreateRoom}
        options={{
          presentation: "modal",
          gestureEnabled: Platform.OS === "ios",
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      <Stack.Screen name="sendImages" component={SendImages} />
      <Stack.Screen
        name="elementCall"
        component={ElementCall}
        options={{
          presentation: "modal",
          gestureEnabled: false,
        }}
      />
      <Stack.Screen
        name="setUpRecoveryKey"
        component={SetUpRecoveryKey}
        options={{
          presentation: "modal",
          gestureEnabled: Platform.OS === "ios",
          ...TransitionPresets.ModalPresentationIOS,
        }}
      />
      {children}
    </Stack.Navigator>
  );
};

