import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  MessageType_Tags,
  MsgLikeKind_Tags,
  ReceiptType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineItemContent_Tags,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import { getEventId } from "modules/matrix-client/utils";
import { NavigationContainerRef } from "modules/navigation/const";
import { useCallback, useEffect, useRef, useState } from "react";

/** Maximum age for a verification request to be considered valid (5 minutes) */
const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;

/** Check if an event is a verification request */
const isVerificationRequest = (event: EventTimelineItem): boolean => {
  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
  const kind = event.content.inner.content.kind;
  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
  const msgType = kind.inner.content.msgType;
  return (
    msgType?.tag === MessageType_Tags.Other &&
    msgType.inner.msgtype === "m.key.verification.request"
  );
};

/** Check if a verification request is recent enough to be handled */
const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
  const eventTimestamp = Number(event.timestamp);
  const now = Date.now();
  const age = now - eventTimestamp;
  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
};

const handleVerificationRequest = (info: {
  senderId: string;
  flowId: string;
}) => {
  NavigationContainerRef.navigate("verifyUser", {
    userId: info.senderId,
    flowId: info.flowId,
  });
};

interface Props {
  room: RoomInterface | undefined;
  roomId: string;
}

export const useRoomTimeline = ({ room, roomId }: Props) => {
  const [events, setEvents] = useState<EventTimelineItem[]>([]);
  const [loadingMessage, setLoadingMessage] = useState(true);
  /** Track processed verification request IDs to avoid duplicates */
  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
  const [refreshing, setRefreshing] = useState(false);
  const [updateTrigger, setUpdateTrigger] = useState(0);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineRef = useRef<TimelineInterface | null>(null);
  const isPaginatingRef = useRef(false);
  const timelinePaginateNumber = useRef<number>(20);

  const upsertEvents = (incoming: EventTimelineItem[]) => {
    setEvents((prev) => {
      const next = [...prev];
      for (const e of incoming) {
        const id = getEventId(e);
        if (!id) continue;
        if (!eventIdsRef.current.has(id)) {
          eventIdsRef.current.add(id);
          next.push(e);
        }
      }
      return next;
    });
  };

  const checkForVerificationRequests = useCallback(
    (incoming: EventTimelineItem[]) => {
      for (const event of incoming) {
        if (event.isOwn) continue;

        if (
          !isVerificationRequest(event) ||
          !isRecentVerificationRequest(event)
        ) {
          continue;
        }

        const flowId = getEventId(event);
        if (!flowId) continue;

        if (processedVerificationRequestsRef.current.has(flowId)) continue;

        processedVerificationRequestsRef.current.add(flowId);

        handleVerificationRequest({
          senderId: event.sender,
          flowId,
        });

        // Only handle one at a time
        break;
      }
    },
    [],
  );

  const markAsRead = async () => {
    if (!room) return;

    try {
      await room.markAsRead(ReceiptType.Read);
    } catch (error) {
      console.error("Failed to mark room as read:", error);
    }
  };

  const loadMoreMessages = async () => {
    if (!room || !timelineRef.current) return;

    isPaginatingRef.current = true;
    setRefreshing(true);

    try {
      await timelineRef.current.paginateBackwards(
        timelinePaginateNumber.current,
      );
      timelinePaginateNumber.current += 20;
    } catch (error) {
      console.error("Failed to load more messages:", error);
    } finally {
      setRefreshing(false);
      isPaginatingRef.current = false;
    }
  };

  useEffect(() => {
    if (!room) return;

    // Reset state when room changes

